def transform(grid):
    """Count the two vertical T orientations and encode their counts in 3x3 panels."""
    h, w = len(grid), len(grid[0])
    seen = set()
    above = below = 0

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == 2 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            if len(cells) != 4:
                continue
            row_counts = {}
            for y, x in cells:
                row_counts[y] = row_counts.get(y, 0) + 1
            bar_rows = [y for y, n in row_counts.items() if n == 3]
            stem_rows = [y for y, n in row_counts.items() if n == 1]
            if len(bar_rows) == 1 and len(stem_rows) == 1:
                if stem_rows[0] < bar_rows[0]:
                    above += 1
                else:
                    below += 1

    out = [[0] * 6 for _ in range(3)]
    # Counts are shown using corner marks: TL, BL, TR, BR.
    slots = ((0, 0), (2, 0), (0, 2), (2, 2))
    for count, color, offset in ((above, 3, 0), (below, 1, 3)):
        for r, c in slots[:min(count, 4)]:
            out[r][c + offset] = color
    return out
